#!/usr/bin/env bash\nset -euo pipefail\n\nTS(){ date '+%Y-%m-%d %H:%M:%S'; }\nlog(){ printf '[%s] [%s] [vLLM] %s\n' "$TS" "$1" "$2"; }\nSCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"\nRUNTIME_ENV="${RUNTIME_ENV:-/kaggle/working/runtime-selection.env}"\nLOG_DIR="${LOG_DIR:-/kaggle/working/logs}"\nPID_FILE="$LOG_DIR/vllm.pid"\nVLLM_LOG="$LOG_DIR/vllm.log"\nmkdir -p "$LOG_DIR"\n[ -f "$RUNTIME_ENV" ] || "$SCRIPT_DIR/detect_environment.sh"\nsource "$RUNTIME_ENV"\nMODEL="$SELECTED_MODEL"\nTP_SIZE="$SELECTED_TENSOR_PARALLEL_SIZE"\nGPU_UTIL="$SELECTED_GPU_MEMORY_UTILIZATION"\nINITIAL_CONTEXT="$SELECTED_MAX_MODEL_LEN"\nQUANT="$SELECTED_QUANTIZATION"\nPARSER="$SELECTED_TOOL_CALL_PARSER"\nHOST="${VLLM_HOST:-127.0.0.1}"\nPORT="${VLLM_PORT:-8000}"\n"$SCRIPT_DIR/stop_vllm.sh" >/dev/null 2>&1 || true\ncontexts="$INITIAL_CONTEXT 24576 16384 8192"\nfor CTX in $contexts; do\n  log INFO "Starting model=$MODEL tp=$TP_SIZE context=$CTX parser=$PARSER"\n  args=(python3 -m vllm.entrypoints.openai.api_server --model "$MODEL" --tensor-parallel-size "$TP_SIZE" --gpu-memory-utilization "$GPU_UTIL" --max-model-len "$CTX" --host "$HOST" --port "$PORT" --enable-auto-tool-choice --tool-call-parser "$PARSER")\n  if [ "$QUANT" != "none" ]; then args+=(--quantization "$QUANT"); fi\n  "${args[@]}" >"$VLLM_LOG" 2>&1 &\n  pid=$!; echo "$pid" > "$PID_FILE"\n  ready=false\n  for _ in $(seq 1 90); do\n    if curl -fsS --max-time 3 "http://$HOST:$PORT/v1/models" >/dev/null 2>&1; then ready=true; break; fi\n    kill -0 "$pid" 2>/dev/null || break\n    sleep 2\n  done\n  if [ "$ready" = true ]; then log INFO "vLLM ready"; exit 0; fi\n  kill "$pid" 2>/dev/null || true; wait "$pid" 2>/dev/null || true\n  if grep -Eiq "out of memory|cuda out of memory|not enough memory|failed to initialize" "$VLLM_LOG"; then\n    log WARN "Memory/startup failure at context=$CTX; retrying smaller context."\n  else\n    log ERROR "vLLM failed for a non-memory reason."\n    tail -n 40 "$VLLM_LOG" || true\n    exit 1\n  fi\ndone\nlog ERROR "vLLM failed for all context sizes."\ntail -n 60 "$VLLM_LOG" || true\nexit 1\n